/**
 * The pose library: motions from Quaternius' Universal Animation Library
 * (CC0), all sharing one rig with the posable figures. Each pose is a short
 * motion; `moment` (0–1) is the most drawable point in it, and the scrub
 * slider moves through the rest. Generated by scripts/models/export_quaternius.py.
 */
import manifest from "./poses.json";

export const POSE_LIBRARY_URL = "/models/poses.glb";

export type Pose = {
  id: string;
  label: string;
  category: string;
  /** Length of the motion in seconds. */
  duration: number;
  moment: number;
  thumbnail: string;
};

export const POSES: Pose[] = manifest;

export const POSE_CATEGORIES = ["All", "Standing", "Motion", "Action", "Low", "Seated"] as const;
export type PoseCategory = (typeof POSE_CATEGORIES)[number];

export const DEFAULT_POSE_ID = "Idle_Loop";

export function posesIn(category: PoseCategory): Pose[] {
  return category === "All" ? POSES : POSES.filter((pose) => pose.category === category);
}

export function getPose(id: string): Pose {
  return POSES.find((pose) => pose.id === id) ?? POSES[0];
}
